다음 C 프로그램의 출력 결과는?

#include <stdio.h>
void main() {
     int x = 0x15213F10 >> 4;
     char y = (char) x;
     unsigned char z = (unsigned char) x;
     printf("%d, %u", y, z);
}

다음 C 프로그램의 실행 결과는?

#include <stdio.h>
int funa(int);
void main() {
     printf("%d, %d", funa(5), funa(6));
     return 0;
}

int funa(int n) {
     if(n > 1)
            return (n + (funa(n-2)));
     else
            return (n % 2);
}

다음 C 프로그램의 실행 결과는?

#include <stdio.h>
int C(int v) {
     printf("%d ", v);
     return 1;
}

int main() {
     int a = -2;
     int b = !a;
     printf("%d %d %d %d ", a, b, a&&b, a||b);
     if(b && C(10))
            printf("A ");
     if(b & C(20))
            printf("B ");
     return 0;
}
